{
  "email": "mei.chen@brightline.example",
  "reason": "Ticket EVAL-email-06: user reports mailbox almost full and some emails failing to send. Checking mailbox.percent_used per KB-010."
}

{
  "outcome": "needs_user_info",
  "reply_to_user": "Hi Mei, your mailbox is at about 99% of its 50 GB limit, which is why Outlook is warning you and some emails are not sending. Please try these steps: 1) Empty your Deleted Items and Junk Email folders. 2) In your Inbox and Sent Items, sort by Size, then move or delete the largest messages. For big attachments, save them to OneDrive and remove the email. 3) If you need to keep older mail, let us know and we can turn on Online Archive for you. Mailbox usage can take up to an hour to update, so check again after that. If you're still above 95% after cleaning up, reply to this ticket and we'll review whether you need a larger quota, which needs manager approval.",
  "internal_note": "Checked lookup_user for mei.chen (user_id 9, BL-LT-0109). Mailbox 50890 MB used of 51200 MB quota = 99.4%, over the 90% warning and 100% send-block threshold risk. Account active, not locked, no failed logins. Per KB-010, the user needs to run cleanup first (empty Deleted/Junk, sort by size, archive mail older than a year). Escalation to quota increase only applies if still over 95% after cleanup and the role needs it, so not escalating yet. Ticket waiting on user to complete cleanup and report back. If still over 95% after cleanup, route to manager approval for quota increase or Tier 2. Did not check spam quarantine or device status; not needed for this symptom.",
  "kb_articles": [
    "KB-010"
  ],
  "confidence": "high"
}
